 const stage=canvas.parentElement;stage.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,yaw:state.insp.yaw,elev:state.insp.elev,moved:false};stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4)drag.moved=true;if(drag.moved){state.insp.yaw=clamp(drag.yaw-(e.clientX-drag.x)*.008,-99,99);state.insp.elev=clamp(drag.elev+(e.clientY-drag.y)*.006,-.2,1.5);state.insp.view='custom';}});stage.addEventListener('pointerup',()=>{setTimeout(()=>drag=null,0)});stage.addEventListener('pointercancel',()=>drag=null);stage.addEventListener('wheel',e=>{state.insp.zoom=clamp(state.insp.zoom*Math.exp(e.deltaY*.001),.65,2);e.preventDefault()},{passive:false});addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('jsonDialog').open)return;if(e.repeat)return;if(e.code==='Space'){e.preventDefault();replay();}if(e.code==='KeyP'){clock.paused=!clock.paused;syncUI()}if(/^[1-5]$/.test(e.key))setAlternative(CODES[Number(e.key)-1]);});addEventListener('blur',()=>{drag=null;lastTime=0;});document.addEventListener('visibilitychange',()=>lastTime=0);addEventListener('resize',updateLabels);addEventListener('beforeunload',dispose);
